create table if not exists public.books(user_id uuid not null,book_id text not null,data jsonb not null,updated_at timestamptz default now(),primary key(user_id,book_id));alter table public.books enable row level security;create policy "read own" on public.books for select using(auth.uid()=user_id);create policy "insert own" on public.books for insert with check(auth.uid()=user_id);create policy "update own" on public.books for update using(auth.uid()=user_id);